package fr.roadguard.app;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
public final class TestDownloadedMapStore {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void varint(ByteArrayOutputStream out,long n){while(n>127){out.write((int)(n&127)|128);n>>>=7;}out.write((int)n);}
 static void le(byte[] a,int p,long n,int count){for(int i=0;i<count;i++)a[p+i]=(byte)(n>>>(8*i));}
 static void fixture(File f)throws Exception{java.lang.reflect.Method id=PmtilesReader.class.getDeclaredMethod("tileId",int.class,int.class,int.class);id.setAccessible(true);long tile=(Long)id.invoke(null,6,32,20);byte[] payload={26,4,120,2,10,0};ByteArrayOutputStream d=new ByteArrayOutputStream();for(long n:new long[]{1,tile,1,payload.length,1})varint(d,n);byte[] header=new byte[127];System.arraycopy("PMTiles".getBytes("US-ASCII"),0,header,0,7);header[7]=3;le(header,8,127,8);le(header,16,d.size(),8);le(header,56,127+d.size(),8);le(header,64,payload.length,8);header[97]=1;header[98]=1;header[99]=1;header[100]=6;header[101]=6;le(header,102,-100000000,4);le(header,106,400000000,4);le(header,110,200000000,4);le(header,114,650000000,4);try(OutputStream out=new FileOutputStream(f)){out.write(header);d.writeTo(out);out.write(payload);}}
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("rg-local-first").toFile(),files=new File(root,"files"),cache=new File(root,"cache"),maps=new File(files,"pmtiles");maps.mkdirs();fixture(new File(maps,"test.pmtiles"));AtomicInteger net=new AtomicInteger();VisibleTileCache http=new VisibleTileCache(cache,1000000,0,()->10000L,(u,h)->{net.incrementAndGet();return new VisibleTileCache.Reply(200,DownloadedMapStore.TRANSPARENT,Collections.singletonMap("cache-control","max-age=60"));},d->10000000);DownloadedMapStore store=new DownloadedMapStore(files,http);
 check(store.hasVectors(),"installed map not found");check(store.maxZoom()==6,"archive zoom");check(store.vector(6,32,20)!=null,"local bytes missing");check(store.covers(8,128,80),"overzoom coverage");check(store.raster(8,128,80,true,true)!=null&&net.get()==0,"covered tile contacted network");check(store.raster(6,33,20,true,true)!=null&&net.get()==1,"missing tile not completed by network");check(store.raster(6,34,20,false,true)==null&&net.get()==1,"offline miss contacted network");
 File raster=new File(files,"tiles/6/34/20.png");raster.getParentFile().mkdirs();Files.write(raster.toPath(),DownloadedMapStore.TRANSPARENT);check(store.raster(6,34,20,true,true)!=null&&net.get()==1,"downloaded raster waited for network");check(store.raster(6,34,20,false,true)!=null,"offline raster missing");store.warm(53,2);check(net.get()==1,"local warmup used Internet");check(store.vector(22,-1,0)==null,"invalid tile accepted");check(!store.covers(0,0,0),"regional low zoom hid the whole world");System.out.println("PASS local-first pipeline: "+checks+" checks; local vector/imports bypass network, missing tiles use network, offline and warmup make zero network calls");
 }
}
